package com.tokimusic.app.data.api

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Crypto vectors generated by running the upstream NeteaseCloudMusicApi
 * 4.32.0 `util/crypto.js` itself under Node
 * (workspace/work/NeteaseCloudMusicApi-4.32.0/package/vectors.js).
 * The Kotlin port must be byte-identical to the Node output for the same
 * input, or NetEase rejects the request — a wrong byte here looks exactly
 * like "the API is down" at runtime, so these vectors are the load-bearing
 * check for the whole native rewrite.
 */
class NeteaseCryptoTest {
    private val payload = """{"ids":"[347230]","level":"standard","encodeType":"flac"}"""

    @Test
    fun aesCbcPresetKey_matchesNode() {
        assertEquals(
            "pgHP1O/hr+IboRMAq6HzpN70ojjtkJjTWVuirDjlapXfV/+TYSuDBfzfgkXYE9VS3PWqLtRKps9E3Yp/yDI12w==",
            NeteaseCrypto.aesEncryptCbcBase64(payload, NeteaseCrypto.PRESET_KEY),
        )
    }

    @Test
    fun aesCbcDoubleEncrypt_matchesNode() {
        val first = NeteaseCrypto.aesEncryptCbcBase64(payload, NeteaseCrypto.PRESET_KEY)
        assertEquals(
            "8KomfWfmQs9F6G/A9Qe8UBI2TjyWGeae8cFv7Cu4bYJM/2qllqmORnLyCQVMUMz+yHkTNJjmJoe1VQWQi00QpwkVC/FdNmgImTVmzuUOBIFOku6/iffopsIJz1fiVJui",
            NeteaseCrypto.aesEncryptCbcBase64(first, "AbCdEfGhIjKlMnOp"),
        )
    }

    @Test
    fun weapi_withFixedKey_matchesNode() {
        val result = NeteaseCrypto.weapi(payload, secretKey = "AbCdEfGhIjKlMnOp")
        assertEquals(
            "8KomfWfmQs9F6G/A9Qe8UBI2TjyWGeae8cFv7Cu4bYJM/2qllqmORnLyCQVMUMz+yHkTNJjmJoe1VQWQi00QpwkVC/FdNmgImTVmzuUOBIFOku6/iffopsIJz1fiVJui",
            result.params,
        )
        // encSecKey is RSA of the REVERSED secret key ("pOnMlKjIhGfEdCbA")
        assertEquals(
            "aaed69aed9104b003aac024b0bd6db96a3c47226fe4b93ee57f8e4b49b7255a901e3cc4c675d1e358a8ceead84d1b0f079bfe02f10745216ed50961a5ebfd946c20f1698586a4d692ba4b932d1f0618f230d9b27ca10ee557ec9bab3d9cb8f14e2a97adbd67b237ec377f2375896f886bb86407acd611eb15aca2ea729902133",
            result.encSecKey,
        )
    }

    @Test
    fun rsaEncrypt_matchesNode() {
        assertEquals(
            "aaed69aed9104b003aac024b0bd6db96a3c47226fe4b93ee57f8e4b49b7255a901e3cc4c675d1e358a8ceead84d1b0f079bfe02f10745216ed50961a5ebfd946c20f1698586a4d692ba4b932d1f0618f230d9b27ca10ee557ec9bab3d9cb8f14e2a97adbd67b237ec377f2375896f886bb86407acd611eb15aca2ea729902133",
            NeteaseCrypto.rsaEncryptNoPadding("pOnMlKjIhGfEdCbA"),
        )
    }

    @Test
    fun eapi_matchesNode() {
        assertEquals(
            "318C28BB58E73FE0D49F8BE24280F60F48B734C591F9703EE2833D7209B55C7E76A27F90AB34D7A9644B103089FF5A9CC3F678B1FD47287EEAE5FEADB300EAD16B209084F18A6E1C4B9A907AD5F5E8B53DD9703FAC31890E5ED12D68D74B6ADBD55D4343A2CE4F77D0AB3DD5730CBC3D",
            NeteaseCrypto.eapi("/api/v2/banner/get", """{"clientType":"iphone"}""").params,
        )
    }

    @Test
    fun eapi_decryptsToTaggedPlaintext() {
        val params = NeteaseCrypto.eapi("/api/v2/banner/get", """{"clientType":"iphone"}""").params
        val plain = NeteaseCrypto.aesDecryptEcbHex(params, NeteaseCrypto.EAPI_KEY)
        assertTrue(plain.startsWith("/api/v2/banner/get-36cd479b6b5-{\"clientType\":\"iphone\"}-36cd479b6b5-"))
    }

    @Test
    fun linuxapi_matchesNode() {
        assertEquals(
            "A0D9583F4C5FF68DE851D2893A49DE98FAFB24399F27B4F7E74C64B6FC49A965CFA972FA5EA3D6247CD6247C8198CB8724902E133AF06ABB1602F129E968462DBEE114A765A8945CF01F463F0A183F1EDAB52A424E8333F8034CEF86AFA86745E702478ED4773052C6F605ED77B5C32B",
            NeteaseCrypto.linuxapi(
                """{"method":"POST","url":"https://music.163.com/api/song/detail","params":{"c":"[{\"id\":347230}]"}}""",
            ).params,
        )
    }

    @Test
    fun cloudmusicDllEncodeId_matchesNode() {
        assertEquals(
            "drXR0SbJ5Y9TINmYRcAI6g==",
            NeteaseCrypto.cloudmusicDllEncodeId("A1B2C3D4E5F6A1B2C3D4E5F6A1B2C3D4E5F6A1B2C3D4E5F6A1B2"),
        )
    }

    @Test
    fun generateDeviceId_shape() {
        val id = NeteaseCrypto.generateDeviceId()
        assertEquals(52, id.length)
        assertTrue(id.all { it in '0'..'9' || it in 'A'..'F' })
    }
}
